import type { SourceId } from "./sources";

/**
 * Items for the sources that publish no index (`curated: true` in sources.ts).
 *
 * A curated source is browsed from this list; each item is still fetched from its
 * publisher when it is previewed or installed, so this holds what a card needs to show
 * before that (name, title, description, dependencies) and nothing that can go stale in
 * a way the publisher's own copy would not catch.
 */
export interface CuratedItem {
  name: string;
  title: string;
  description: string;
  dependencies?: string[];
  registryDependencies?: string[];
}

